public static class Theme {
 public static Color Bg=Color.FromArgb(17,22,30),Panel=Color.FromArgb(26,33,44),Ink=Color.FromArgb(239,238,235),Muted=Color.FromArgb(157,161,175),Gold=Color.FromArgb(222,182,116),Green=Color.FromArgb(115,211,176);
 public static Font Font(float size=10,bool bold=false){return new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular);}
 public static Label Label(string text,int x,int y,int w,int h,float size=10,Color? color=null){return new Label{Text=text,Bounds=new Rectangle(x,y,w,h),Font=Font(size),ForeColor=color??Ink,BackColor=Color.Transparent};}
 public static Button Button(string text,Action click){var b=new SoftButton{Text=text,AutoSize=true,Height=34,FlatStyle=FlatStyle.Flat,BackColor=Panel,ForeColor=Ink,Padding=new Padding(9,3,9,3),Font=Font(9),Margin=new Padding(0,0,8,0)};b.FlatAppearance.BorderColor=Color.FromArgb(65,78,96);b.Click+=(s,e)=>click();return b;}
 public static DataGridView Grid(){var g=new DataGridView{Dock=DockStyle.Fill,BackgroundColor=Bg,BorderStyle=BorderStyle.None,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,EnableHeadersVisualStyles=false,GridColor=Panel,Font=Font(10),CellBorderStyle=DataGridViewCellBorderStyle.SingleHorizontal,ColumnHeadersBorderStyle=DataGridViewHeaderBorderStyle.None,RowTemplate={Height=48}};g.DefaultCellStyle.Padding=new Padding(9,0,5,0);g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(21,28,38);g.DefaultCellStyle.BackColor=Bg;g.DefaultCellStyle.ForeColor=Ink;g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(48,57,68);g.DefaultCellStyle.SelectionForeColor=Ink;g.ColumnHeadersDefaultCellStyle.BackColor=Panel;g.ColumnHeadersDefaultCellStyle.ForeColor=Muted;g.ColumnHeadersDefaultCellStyle.Font=Font(9,true);g.ColumnHeadersHeight=43;g.Paint+=(s,e)=>{if(g.Rows.Count==0){using(var f=Font(13,true))TextRenderer.DrawText(e.Graphics,"Nothing to show yet",f,new Rectangle(20,95,g.Width-40,30),Muted,TextFormatFlags.HorizontalCenter);using(var f=Font(9))TextRenderer.DrawText(e.Graphics,"Data appears here as you play or change your filters.",f,new Rectangle(20,130,g.Width-40,48),Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.WordBreak);}};return g;}
 public static void Columns(DataGridView g,params string[] names){foreach(string name in names)g.Columns.Add(name,name);}
 public static void Link(string url){Uri u;if(Uri.TryCreate(url,UriKind.Absolute,out u)&&u.Scheme=="https")Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}
}
public class Article : ScrollableControl {
 public Article(){AutoScroll=true;DoubleBuffered=true;Padding=new Padding(24);}
 protected override void OnTextChanged(EventArgs e){base.OnTextChanged(e);AutoScrollPosition=Point.Empty;Invalidate();}
 protected override void OnResize(EventArgs e){base.OnResize(e);Invalidate();}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;int y=16;int width=Math.Max(100,ClientSize.Width-46);using(var body=Theme.Font(10.5f))using(var heading=Theme.Font(11,true))foreach(string raw in Text.Split('\n')){string line=raw.TrimEnd('\r');bool isHeading=line.Length>0&&line.Length<80&&line==line.ToUpperInvariant()&&line.Any(Char.IsLetter);var f=isHeading?heading:body;int h=line.Length==0?13:(int)Math.Ceiling(g.MeasureString(line,f,width).Height)+7;using(var b=new SolidBrush(isHeading?Theme.Gold:Theme.Ink))g.DrawString(line,f,b,new RectangleF(16,y+AutoScrollPosition.Y,width,h));y+=h;}AutoScrollMinSize=new Size(0,y+20);}
}
