 void BuildLive(){var p=Page("Live match");liveTitle.BackColor=Color.Transparent;liveTitle.Dock=DockStyle.Top;liveTitle.Height=76;liveTitle.Font=Theme.Font(15,true);liveTitle.ForeColor=Theme.Green;p.Controls.Add(liveTitle);var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Vertical,BackColor=Theme.Bg,SplitterWidth=14};split.Size=new Size(1000,480);split.SplitterDistance=550;p.Controls.Add(split);split.BringToFront();Theme.Columns(board,"Position","Minion","Attack","Health","Keywords");Theme.Columns(lobby,"Hero","Tier","Health","Place");split.Panel1.Controls.Add(board);split.Panel1.Controls.Add(Bar("YOUR OBSERVED BOARD · combat buffs may be temporary"));split.Panel2.Controls.Add(lobby);split.Panel2.Controls.Add(Bar("LOBBY · last visible hero state"));}
