 void BuildHeroes(){var p=Page("Hero rankings");Theme.Columns(heroes,"Rank","Hero","Avg place","Pick %","Games");p.Controls.Add(heroes);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=46};SearchStyle(heroSearch);bar.Controls.Add(heroSearch);bar.Controls.Add(Theme.Button("Open selected source",()=>{var h=Selected<HeroRank>(heroes);if(h!=null)Theme.Link(h.url);}));p.Controls.Add(bar);p.Controls.Add(Bar("Search hero names. Lower average placement is better. Selected mode · all ranks · source patch. These are population averages, not lobby-specific odds."));heroSearch.TextChanged+=(s,e)=>FillHeroes();}
 void BuildComps(){var p=Page("Compositions");var split=new SplitContainer{Dock=DockStyle.Fill,SplitterWidth=15};split.Size=new Size(1000,500);split.SplitterDistance=460;Theme.Columns(comps,"Tier","Composition","Avg","Top 4 %");comps.Columns[0].FillWeight=40;comps.Columns[1].FillWeight=190;comps.Columns[2].FillWeight=45;comps.Columns[3].FillWeight=60;split.Panel1.Controls.Add(comps);details.Dock=DockStyle.Fill;details.BackColor=Theme.Panel;details.ForeColor=Theme.Ink;details.Font=Theme.Font(11);split.Panel2.Controls.Add(details);corePreview=new CorePreview(Catalog);split.Panel2.Controls.Add(corePreview);var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=47,Padding=new Padding(0,6,0,0)};actions.Controls.Add(Theme.Button("Pin to overlay",()=>{Overlay.Pinned=selectedComp;Overlay.Invalidate();}));actions.Controls.Add(Theme.Button("Full source guide",()=>{var c=Selected<Comp>(comps);if(c!=null)Theme.Link(c.url);}));split.Panel2.Controls.Add(actions);p.Controls.Add(split);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=43};SearchStyle(compSearch);bar.Controls.Add(compSearch);bar.Controls.Add(Theme.Button("Clear pin",()=>Overlay.Pinned=""));p.Controls.Add(bar);p.Controls.Add(Bar("Source tiers and core setups · select a comp to inspect its pieces. Core overlap is a watchlist, not a recommendation to force a build."));compSearch.TextChanged+=(s,e)=>FillComps();comps.SelectionChanged+=(s,e)=>ShowComp();}
 void BuildCards(){var p=Page("Card library");Theme.Columns(cards,"Tier","Card","Tribe","Attack","Health","Text");cards.Columns[1].FillWeight=170;cards.Columns[5].FillWeight=330;p.Controls.Add(cards);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=45};SearchStyle(cardSearch);bar.Controls.Add(cardSearch);kind.DropDownStyle=ComboBoxStyle.DropDownList;kind.Items.AddRange(new object[]{"Pool minions","Pool spells","Heroes","All BG cards"});kind.SelectedIndex=0;kind.Width=150;bar.Controls.Add(kind);tribe.DropDownStyle=ComboBoxStyle.DropDownList;tribe.Items.AddRange(new object[]{"All tribes","BEAST","DEMON","DRAGON","ELEMENTAL","MECHANICAL","MURLOC","NAGA","PIRATE","QUILBOAR","UNDEAD"});tribe.SelectedIndex=0;tribe.Width=155;bar.Controls.Add(tribe);p.Controls.Add(bar);p.Controls.Add(Bar("HearthstoneJSON · pool flags reflect the client database and may lag server hotfixes. Search names or card text; tavern tier appears in the first column."));cardSearch.TextChanged+=(s,e)=>FillCards();kind.SelectedIndexChanged+=(s,e)=>FillCards();tribe.SelectedIndexChanged+=(s,e)=>FillCards();}
 void BuildStats(){var p=Page("My stats");Theme.Columns(historyGrid,"Finished","Hero","Place","Turns","Client build");p.Controls.Add(historyGrid);statsTitle.Dock=DockStyle.Top;statsTitle.Height=65;statsTitle.Font=Theme.Font(15,true);statsTitle.ForeColor=Theme.Green;p.Controls.Add(statsTitle);var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=43};bar.Controls.Add(Theme.Button("Import a Power log",()=>Import()));bar.Controls.Add(Theme.Button("Export CSV",()=>Export()));p.Controls.Add(bar);p.Controls.Add(Bar("Local results for the selected mode · duplicate matches are ignored. MMR and results missing from the log are not guessed."));}
