 static T Selected<T>(DataGridView g) where T:class{return g.SelectedRows.Count>0?g.SelectedRows[0].Tag as T:null;}
 public void ShowDashboard(){Show();WindowState=FormWindowState.Normal;Activate();}
 async void OnCombat(FightSnapshot f){ArtCache.Request(f.Enemy.Concat(f.Friendly).Select(x=>x.CardId),Catalog.Cards.build);if((reader!=null&&reader.CaughtUp)&&!Combat.Busy)await Combat.Run(f);}
 public void SavePreferences(){SaveSettings();}public void SaveSession(){try{Store.Write(Catalog.Duos?"session-duos.json":"session.json",Session);}catch(Exception e){error="Session save failed: "+e.Message;}}
 public void SwitchMode(bool duos){if(Catalog.Duos==duos)return;SaveSession();Catalog.Duos=duos;Settings.DataMode=duos?"Duos":"Solo";Session=Store.Read(duos?"session-duos.json":"session.json",new SessionData());if(Rating!=null)Rating.ResetConfirmation();if(Overlay!=null){Overlay.Guide.RefreshRows(true);Overlay.Tools.FilterCards();}Populate();SaveSettings();}
 void SaveSettings(){try{Store.Write("settings.json",Settings);}catch(Exception e){error="Could not save settings: "+e.Message;}UpdateSources();}
 void Populate(){FillHeroes();FillComps();FillCards();FillHistory();UpdateSources();}
 void FillHeroes(){heroes.Rows.Clear();foreach(var h in Catalog.Meta.heroes.Where(x=>x.name.IndexOf(heroSearch.Text,StringComparison.OrdinalIgnoreCase)>=0).OrderBy(x=>x.rank)){int i=heroes.Rows.Add(h.rank,h.name,h.avg.ToString("0.00"),h.pick.ToString("0.0"),h.games);heroes.Rows[i].Tag=h;}}
 void FillComps(){comps.Rows.Clear();foreach(var c in Catalog.BuildMeta.comps.Where(x=>x.name.IndexOf(compSearch.Text,StringComparison.OrdinalIgnoreCase)>=0).OrderBy(x=>"SABCDF".IndexOf(x.tier)).ThenBy(x=>x.avg)){int i=comps.Rows.Add(c.tier,c.name,c.unranked?"—":c.avg.ToString("0.0"),c.unranked?"—":c.top4.ToString("0.0"));comps.Rows[i].Tag=c;}ShowComp();}
 void FillCards(){cards.Rows.Clear();foreach(var c in Catalog.Cards.cards.Where(c=>Catalog.Available(c)&&(kind.SelectedIndex==0?c.pool:kind.SelectedIndex==1?c.spell:kind.SelectedIndex==2?c.hero:true)&&(tribe.SelectedIndex<=0||c.tribe.Contains(tribe.Text))&&(c.name+" "+c.text).IndexOf(cardSearch.Text,StringComparison.OrdinalIgnoreCase)>=0).OrderBy(x=>x.tier).ThenBy(x=>x.name)){cards.Rows.Add(c.tier==0?"—":c.tier.ToString(),c.name,c.tribe,c.attack,c.health,c.text);}}
 void ShowComp(){var c=Selected<Comp>(comps);if(c==null)return;selectedComp=c.name;if(corePreview!=null){corePreview.Comp=c;corePreview.Invalidate();}var lines=new List<string>{c.name.ToUpperInvariant(),"", "Tier "+c.tier+"  ·  "+c.avg.ToString("0.0")+" avg placement",c.first+"% first  ·  "+c.top4+"% top four  ·  "+c.games+" games","",Catalog.Freshness,"", "CORE PIECES (not a positioning order)",""};foreach(var id in c.core){var card=Catalog.Get(id);lines.Add("• "+Catalog.Name(id)+(card==null?" [missing card data]":"  ·  Tavern "+card.tier+(card.pool?"":" [not flagged in pool]")));if(card!=null)lines.Add("   "+card.text);lines.Add("");}lines.Add("OPTIONAL PIECES");foreach(var id in c.addons)lines.Add("• "+Catalog.Name(id));lines.AddRange(new[]{"","SETUP CHECKLIST","Identify the core engine before committing. Keep room to buy and cycle cards. Use each card's current text to decide trigger order, and inspect the opponent before changing positioning.","","The source guide has the build-specific play pattern. Population placement does not predict your current board's combat result.","","Source: "+c.url,"Scope: "+Catalog.BuildMeta.scope});if(!String.IsNullOrEmpty(c.detailError))lines.Add("Board unavailable: "+c.detailError);if(c.unranked){lines.RemoveRange(2,3);lines.InsertRange(2,new[]{"DUOS MECHANIC GUIDE · UNRANKED",c.notes??"","No verified Duos build-placement statistics are available."});}details.Text=String.Join(Environment.NewLine,lines);}
 void FillHistory(){historyGrid.Rows.Clear();var results=history.Where(r=>(r.mode??"").Contains("DUO")==Catalog.Duos).ToList();foreach(var r in results.OrderByDescending(x=>x.endedAt)){DateTime dt;string date=DateTime.TryParse(r.endedAt,out dt)?dt.ToLocalTime().ToString("dd MMM HH:mm"):r.endedAt;historyGrid.Rows.Add(date,Catalog.Name(r.hero),r.placement,r.turns,r.build);}statsTitle.Text=results.Count==0?"No recorded matches yet":results.Count+" matches    ·    "+results.Average(x=>x.placement).ToString("0.00")+" avg place    ·    "+(100.0*results.Count(x=>x.placement<=(Catalog.Duos?2:4))/results.Count).ToString("0")+(Catalog.Duos?"% top two    ·    ":"% top four    ·    ")+results.Count(x=>x.placement==1)+" wins";}
 void Record(MatchRecord r){if(history.Any(x=>x.key==r.key))return;history.Add(r);if(reader!=null&&!importing){bool duo=(r.mode??"").Contains("DUO");if(duo==Catalog.Duos){Session.Add(r);SaveSession();}else{var otherSession=Store.Read(duo?"session-duos.json":"session.json",new SessionData());otherSession.Add(r);Store.Write(duo?"session-duos.json":"session.json",otherSession);}}try{Store.Write("history.json",history);}catch(Exception e){error="History save failed: "+e.Message;}FillHistory();}
 void UpdateSources(){sources.Text=String.Join("\n",new[]{
 "TAVERNLENS — GET CONNECTED","",
 "Exit the previous TavernLens from its tray menu, then run TavernLens.exe. Use Solo or Duos Battlegrounds in windowed or borderless mode.","",
 "Minions opens the illustrated tribe/tavern-tier browser. Builds opens illustrated core and optional cards. Fights opens the latest recorded board for each opponent. Hover a native leaderboard portrait for a row of remembered minion pictures.","",
 "Ctrl+Shift+O shows/hides everything. Ctrl+Shift+Space locks/unlocks interaction. Ctrl+Shift+D opens the dashboard. Closing the dashboard keeps the tray app running.","",
 "Hearthstone folder: "+Settings.HearthstonePath,"Log: "+(String.IsNullOrEmpty(logPath)?"Waiting for Power.log":logPath),"",
 "COMBAT ODDS","",
 "Firestone simulator 1.1.750 runs locally, up to 1,500 simulations per combat. The panel shows win, draw and loss estimates once minion attacks begin. Previous-fight results are labeled during recruitment.","",
 "EXPERIMENTAL: odds are conditional on visible log state. Unknown opponent hand, some global counters, Dark Gift state and unhandled effects can materially change the result. Sampling error is not the only source of error. Unknown cards, unsupported secret/quest/anomaly state, timeouts and new untested card builds withhold results.","",
 "OPPONENT HISTORY","",
 "Snapshots preserve minion order, card identity, attack, health and keywords at combat opening or before the first attack. Start-of-combat effects may already have happened. Boards are per opponent and reset for a new match. Hero-position mapping must be known from the log; an unmapped portrait does not show a guessed board.","",
 "DATA SOURCES","",Catalog.Freshness,"Card build: "+Catalog.Cards.build+" · checked "+Catalog.Cards.updatedAt,"Rankings: "+Catalog.Meta.source,Catalog.Meta.scope,"Retrieved: "+Catalog.Meta.updatedAt,"Official announcement: "+Catalog.Patch.title,Catalog.Patch.url,"",
 "Cards, rankings and patch news refresh on launch and hourly. Images are cached from HearthstoneJSON. Failed sources retain their last usable cache. Simulator program updates require compatibility testing; it will not silently claim support for a new card build.",String.Join("\n",Catalog.Status.errors),"",
 "LOGGING & LIMITS","",
 "If Power.log is missing, run Enable-Logging.ps1 and restart Hearthstone. It backs up log.config and preserves other sections. No memory injection or game input automation is used. Duos, MMR and automated lobby-tribe filtering are not supported.","",
 "Combat snapshots remain local. No account names or log uploads are sent. Artwork requests contain card IDs in the image URLs. Public stats are all-ranks population data, and core-piece lists are not positioning instructions.","",
 "Independent personal tool. Hearthstone art and card text belong to Blizzard. Statistics are attributed to Battlegrounds Buddy / Firestone community data. Simulator dependency notices are included in the simulator folder."
 });}
 async void RefreshWeb(){if(updating)return;updating=true;lastUpdate=DateTime.UtcNow;connection.Text="Refreshing public data…";try{int result=await Task.Run(()=>{var p=Process.Start(new ProcessStartInfo(Path.Combine(Store.Root,"runtime","node.exe"),"\""+Path.Combine(Store.Root,"src","update-data.cjs")+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Store.Root});if(!p.WaitForExit(180000)){p.Kill();throw new Exception("Refresh timed out; cached data retained.");}int code=p.ExitCode;p.Dispose();return code;});var refreshed=await Task.Run(()=>new Catalog());Catalog.Adopt(refreshed);Populate();error=result==0?"":"Some sources could not refresh. See Setup and sources.";}catch(Exception e){error=e.Message;}finally{updating=false;}}
 void Tick(){
  if(closing)return;
  if(lastUpdate==DateTime.MinValue||(DateTime.UtcNow-lastUpdate).TotalHours>=1)RefreshWeb();
  IntPtr target=IntPtr.Zero;bool gameRunning=false;foreach(var p in Process.GetProcessesByName("Hearthstone")){using(p){gameRunning=true;if(p.MainWindowHandle!=IntPtr.Zero){target=p.MainWindowHandle;break;}}}
  try{
   if(target!=IntPtr.Zero&&(DateTime.UtcNow-lastDiscover).TotalSeconds>=3){lastDiscover=DateTime.UtcNow;string root=Path.Combine(Settings.HearthstonePath,"Logs");if(Directory.Exists(root)){var newest=Directory.GetDirectories(root).OrderByDescending(x=>Directory.GetLastWriteTimeUtc(x)).FirstOrDefault();string candidate=newest==null?Path.Combine(root,"Power.log"):Path.Combine(newest,"Power.log");if(File.Exists(candidate)&&(candidate!=logPath||File.GetCreationTimeUtc(candidate)!=logCreated)){if(reader!=null)reader.Dispose();reader=new LiveReader(candidate);logPath=candidate;logCreated=File.GetCreationTimeUtc(candidate);string scenePath=Path.Combine(Path.GetDirectoryName(candidate),"LoadingScreen.log");sceneTail.Dispose();Scenes=new SceneState();if(File.Exists(scenePath))sceneTail.Open(scenePath);State=new MatchState{Stream=candidate};State.OnComplete=Record;State.OnCombat=OnCombat;UpdateSources();}}}
   if(target!=IntPtr.Zero&&!String.IsNullOrEmpty(logPath)){if(reader!=null){State=reader.Latest;if(State.Battlegrounds&&State.Started&&!State.Complete&&!Scenes.InLobby)SwitchMode(State.Duos);if(State.Complete){State.Fights.Clear();State.LastFights.Clear();State.TeamBoards.Clear();State.CurrentFight=null;}foreach(var result in reader.Drain())Record(result);if(reader.Error!="")error="Log reader: "+reader.Error;}sceneTail.Poll(Scenes.Feed);}
  }catch(Exception e){error="Log reader: "+e.Message;}
  var foreground=Native.GetForegroundWindow();Rating.Tick(gameRunning?new IntPtr(1):IntPtr.Zero,Scenes.InLobby&&foreground==target);if(target!=IntPtr.Zero)preview=false;if(preview){Overlay.Follow(Handle,Visible);}else Overlay.Follow(target,!Rating.Selecting&&!Scenes.Loading&&(Scenes.InLobby||(State.Battlegrounds&&(reader!=null&&reader.CaughtUp)&&(Scenes.Scene==""||Scenes.Scene=="GAMEPLAY")))&&(foreground==target||Native.IsOurWindow(foreground)));
  if(!updating)connection.Text=target==IntPtr.Zero?"WAITING FOR HEARTHSTONE":String.IsNullOrEmpty(logPath)?"GAME FOUND · waiting for Power.log":(reader!=null&&!reader.CaughtUp)?"RECOVERING CURRENT MATCH…":!State.Battlegrounds?"CONNECTED · ready for your next match":"CONNECTED · "+(Catalog.Duos?"Duos · ":"Solo · ")+State.Phase;
  fresh.Text=Catalog.Freshness+(String.IsNullOrEmpty(error)?"":"\n"+error);
  if(State.CurrentFight!=null&&(State.CurrentFight.Stage=="After start-of-combat"||(State.Duos&&State.CurrentFight.FriendlyPartner!=null))&&(reader!=null&&reader.CaughtUp)&&Combat.Result.key!=State.CurrentFight.Key&&!Combat.Busy)OnCombat(State.CurrentFight);if(++renders%2==0&&Visible)RenderLive();
 }
 void RenderLive(){var s=State;var h=s.Hero;liveTitle.Text=!s.Battlegrounds?"Ready when you enter Battlegrounds":"Turn "+s.Turn+" · "+s.Phase+" · "+Catalog.Name(h==null?null:h.CardId)+"\n"+(h==null?"":Math.Max(0,h.N("HEALTH")-h.N("DAMAGE"))+" health + "+h.N("ARMOR")+" armor");string signature=s.Key+"|"+s.Phase+"|"+String.Join(";",s.Board(s.Controller).Concat(s.Lobby).Select(x=>x.Id+":"+x.CardId+":"+String.Join(",",x.Tags.OrderBy(t=>t.Key).Select(t=>t.Key+"="+t.Value))));if(signature==liveSignature)return;liveSignature=signature;board.Rows.Clear();if(s.Battlegrounds)foreach(var x in s.Board(s.Controller)){string keys=String.Join(", ",new[]{"TAUNT","DIVINE_SHIELD","REBORN","WINDFURY","VENOMOUS"}.Where(k=>x.N(k)>0).Select(k=>k.Replace('_',' ')));board.Rows.Add(x.N("ZONE_POSITION"),Catalog.Name(x.CardId),x.N("ATK"),Math.Max(0,x.N("HEALTH")-x.N("DAMAGE")),keys);}lobby.Rows.Clear();if(s.Battlegrounds)foreach(var x in s.Lobby)lobby.Rows.Add(Catalog.Name(x.CardId),x.N("PLAYER_TECH_LEVEL"),Math.Max(0,x.N("HEALTH")-x.N("DAMAGE")),x.N("PLAYER_LEADERBOARD_PLACE"));}
 async void Import(){if(importing)return;using(var d=new OpenFileDialog{Filter="Hearthstone Power logs|Power*.log|Log files|*.log",InitialDirectory=Path.Combine(Settings.HearthstonePath,"Logs")}){if(d.ShowDialog()!=DialogResult.OK)return;importing=true;connection.Text="Importing match log…";try{var results=await Task.Run(()=>{var list=new List<MatchRecord>();var state=new MatchState{Stream=d.FileName};state.OnComplete=list.Add;foreach(var line in File.ReadLines(d.FileName))state.Feed(line);return list;});int before=history.Count;foreach(var r in results)Record(r);MessageBox.Show((history.Count-before)+" results imported. Incomplete or unrecognized results are skipped.","TavernLens");}catch(Exception e){MessageBox.Show(e.Message,"Import failed");}finally{importing=false;}}}
 void Export(){using(var d=new SaveFileDialog{Filter="CSV|*.csv",FileName="TavernLens-history.csv"}){if(d.ShowDialog()!=DialogResult.OK)return;try{File.WriteAllLines(d.FileName,new[]{"finished,hero,placement,turns,build,mode"}.Concat(history.Select(x=>Csv(x.endedAt)+","+Csv(Catalog.Name(x.hero))+","+x.placement+","+x.turns+","+Csv(x.build)+","+Csv(x.mode))));}catch(Exception e){MessageBox.Show(e.Message,"Export failed");}}}
 static string Csv(string value){value=value??"";if(value.Length>0&&"=+-@".Contains(value[0]))value="'"+value;return "\""+value.Replace("\"","\"\"")+"\"";}
 protected override void WndProc(ref Message m){if(m.Msg==0x312){int id=m.WParam.ToInt32();if(id==1){Settings.OverlayEnabled=!Settings.OverlayEnabled;SaveSettings();}else if(id==2)Overlay.SetInteractive(!Overlay.Interactive);else if(id==3)ShowDashboard();}base.WndProc(ref m);}
 protected override void Dispose(bool disposing){if(disposing){timer.Stop();timer.Dispose();tail.Dispose();if(reader!=null)reader.Dispose();if(tray!=null)tray.Dispose();if(Overlay!=null)Overlay.Dispose();}base.Dispose(disposing);}
 public void CaptureSidebar(string output){Session=new SessionData();lastUpdate=DateTime.UtcNow;preview=true;Show();Application.DoEvents();Overlay.SetInteractive(true);Overlay.Follow(Handle,true);Directory.CreateDirectory(output);BoardTests.Render(output);SaveShot(this,Path.Combine(output,"App.png"));Overlay.Guide.SelectMode(0);Application.DoEvents();SaveShot(Overlay,Path.Combine(output,"Right-Minions.png"));Overlay.Guide.Preview.Display("BG31_803",null,Overlay.Guide,0);Application.DoEvents();SaveShot(Overlay.Guide.Preview,Path.Combine(output,"Card-Hover.png"));try{using(var screen=new Bitmap(Overlay.Guide.Preview.Width,Overlay.Guide.Preview.Height)){using(var g=Graphics.FromImage(screen))g.CopyFromScreen(Overlay.Guide.Preview.Location,Point.Empty,screen.Size);screen.Save(Path.Combine(output,"Native-Hover.png"));}}catch(System.ComponentModel.Win32Exception){File.WriteAllText(Path.Combine(output,"Native-capture-note.txt"),"Desktop capture is unavailable in this execution session; compositor alpha attributes are verified by native tests.");}Overlay.Guide.Preview.Hide();Overlay.Guide.SelectMode(1);Application.DoEvents();SaveShot(Overlay,Path.Combine(output,"Right-Builds.png"));SaveShot(Overlay.SessionBox,Path.Combine(output,"Left-Session.png"));if(Catalog.BuildMeta.comps.Count>0){Overlay.Guide.OpenBuild(Catalog.BuildMeta.comps[0].name);Application.DoEvents();SaveShot(Overlay,Path.Combine(output,"Build-Details.png"));}Overlay.Pinned=Catalog.BuildMeta.comps.First().name;Overlay.Guide.Collapsed=true;Overlay.Guide.RefreshRows();Overlay.Guide.Sync();Overlay.Follow(Handle,true);Application.DoEvents();SaveShot(Overlay,Path.Combine(output,"Collapsed.png"));closing=true;Close();}
 static void SaveShot(Control c,string path){var until=DateTime.UtcNow.AddMilliseconds(250);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}using(var image=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path);}}
 public void CapturePreview(string output){lastUpdate=DateTime.UtcNow;Show();Application.DoEvents();foreach(TabPage page in tabs.TabPages){tabs.SelectedTab=page;Application.DoEvents();using(var shot=new Bitmap(Width,Height)){DrawToBitmap(shot,new Rectangle(0,0,Width,Height));shot.Save(Path.Combine(Path.GetDirectoryName(output),"Page-"+tabs.SelectedIndex+".png"));}}tabs.SelectedIndex=2;ShowComp();Application.DoEvents();using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(output);}Overlay.Tools.Open(0,new Rectangle(20,20,1100,740));Application.DoEvents();using(var b=new Bitmap(Overlay.Tools.Width,Overlay.Tools.Height)){Overlay.Tools.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(Path.GetDirectoryName(output),"Minion-browser.png"));}Overlay.Tools.Tabs.SelectedIndex=1;Application.DoEvents();using(var b=new Bitmap(Overlay.Tools.Width,Overlay.Tools.Height)){Overlay.Tools.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(Path.GetDirectoryName(output),"Build-guide.png"));}Overlay.Tools.Tabs.SelectedIndex=2;Application.DoEvents();using(var shot=new Bitmap(Overlay.Tools.Width,Overlay.Tools.Height)){Overlay.Tools.DrawToBitmap(shot,new Rectangle(Point.Empty,shot.Size));shot.Save(Path.Combine(Path.GetDirectoryName(output),"Fight-history.png"));}Size=MinimumSize;tabs.SelectedIndex=3;Application.DoEvents();using(var shot=new Bitmap(Width,Height)){DrawToBitmap(shot,new Rectangle(Point.Empty,shot.Size));shot.Save(Path.Combine(Path.GetDirectoryName(output),"Compact-layout.png"));}closing=true;Close();}
}
public static class Program {public static bool DiagnosticMode;
 [STAThread] public static void Main(string[] args){DiagnosticMode=args.Length>0;Native.SetProcessDPIAware();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(args.Length>0&&args[0]=="--test"){Tests.Run(args.Skip(1).ToArray());return;}using(var main=new Main()){if(args.Length==2&&args[0]=="--duos-screenshots"){main.SwitchMode(true);main.CaptureSidebar(args[1]);return;}if(args.Length==2&&args[0]=="--sidebar-screenshots"){main.CaptureSidebar(args[1]);return;}if(args.Length==2&&args[0]=="--screenshot"){main.CapturePreview(args[1]);return;}Application.Run(main);}}catch(Exception e){File.WriteAllText(Path.Combine(Store.Root,"error.txt"),e.ToString());if(args.Length==0)MessageBox.Show(e.Message,"TavernLens could not start");Environment.ExitCode=1;}}
}
